import{_ as a,o as e,a as l,b as i}from"./app.DKoEZOcr.js";const d="/ascendc.github.io/pr/5487/assets/arange_algorithm_diagram.DcbjyvSs.png",v=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"索引计算","link":"/api/SIMD-API/adv_api/index_compute/index_compute"},{"text":"Arange","link":"/api/SIMD-API/adv_api/index_compute/Arange"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/index_compute/Arange.md","filePath":"api/SIMD-API/adv_api/index_compute/Arange.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"实现原理","slug":"实现原理","link":"#实现原理"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787132628000}'),s={name:"api/SIMD-API/adv_api/index_compute/Arange.md"};function r(n,t,c,h,o,p){return e(),l("div",null,[...t[0]||(t[0]=[i('<div><article class="markdown-body"><h1>Arange</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>给定起始值，等差值和长度，返回一个等差数列。</p><h2 id="实现原理">实现原理<a class="header-anchor" href="#实现原理">​</a></h2><p>以float类型，ND格式，firstValue和diffValue输入Scalar为例，描述Arange高阶API内部算法框图，如下图所示。</p><p><strong>图1</strong> Arange算法框图<br><img src="'+d+`" alt title="Arange算法框图"></p><p>计算过程分为如下几步，均在Vector上进行：</p><ol><li>等差数列长度8以内步骤：按照firstValue和diffValue的值，使用SetValue实现等差数列扩充，扩充长度最大为8，如果等差数列长度小于8，算法结束；</li><li>等差数列长度8至64的步骤：对第一步中的等差数列结果使用Adds进行扩充，最大循环7次扩充至64，如果等差数列长度小于64，算法结束；</li><li>等差数列长度64以上的步骤：对第二步中的等差数列结果使用Adds进行扩充，不断循环直至达到等差数列长度为止。</li></ol><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;typename T&gt;
__aicore__ inline void Arange(const LocalTensor&lt;T&gt;&amp; dst, const T firstValue, const T diffValue, const int32_t count)
</code></pre></div><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>T</td><td>操作数的数据类型。不同型号支持的数据类型请参考<a href="#li73338460199">支持的数据类型</a>。</td></tr></tbody></table><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。dst的大小应大于等于count * sizeof(T)。<br><br>类型为<a href="../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>firstValue</td><td>输入</td><td>等差数列的首个元素值。</td></tr><tr><td>diffValue</td><td>输入</td><td>等差数列元素之间的差值，应大于等于0。</td></tr><tr><td>count</td><td>输入</td><td>等差数列的长度。count&gt;0。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><p>当前仅支持ND格式的输入，不支持其他格式。</p></li><li><p>支持的数据类型<a id="li73338460199"></a></p><div data-filter="950"><p>Ascend 950PR/Ascend 950DT，支持的数据类型为：int16_t、half、int32_t、float、int64_t。</p></div><div data-filter="A3"><p>Atlas A3 训练系列产品/Atlas A3 推理系列产品，支持的数据类型为：int16_t、half、int32_t、float。</p></div><div data-filter="910b"><p>Atlas A2 训练系列产品/Atlas A2 推理系列产品，支持的数据类型为：int16_t、half、int32_t、float。</p></div><div data-filter="310p"><p>Atlas 推理系列产品AI Core，支持的数据类型为：int16_t、half、int32_t、float。</p></div></li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><p>完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/04_advanced_api/06_index/arange">Arange样例</a>。</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>// dst：输出Tensor
// firstValue_：等差数列首个元素值
// diffValue_：等差数列的公差
// count_：等差数列的长度
AscendC::Arange&lt;T&gt;(dst, static_cast&lt;T&gt;(firstValue_), static_cast&lt;T&gt;(diffValue_), count_);
</code></pre></div></article></div>`,1)])])}const _=a(s,[["render",r]]);export{v as __pageData,_ as default};
